import{_ as t,o,c as r,ag as i}from"./chunks/framework.IxO3mcwW.js";const e="/getbiji-docs/images/vocabulary-01.png",l="/getbiji-docs/images/vocabulary-02.png",s="/getbiji-docs/images/vocabulary-03.png",b=JSON.parse('{"title":"语音词库","description":"","frontmatter":{},"headers":[],"relativePath":"voice/vocabulary.md","filePath":"voice/vocabulary.md","lastUpdated":1773215704000}'),n={name:"voice/vocabulary.md"};function p(d,a,c,u,g,h){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="语音词库" tabindex="-1">语音词库 <a class="header-anchor" href="#语音词库" aria-label="Permalink to &quot;语音词库&quot;">​</a></h1><blockquote><p>语音词库——让 AI 准确听懂每一个专业词</p></blockquote><p>添加你常用的专有名词、人名、术语，录音转写不再写错</p><p>录音转写时，专有名词、人名、行业术语最容易被误识别——&quot;柳比歇夫&quot;可能变成&quot;刘比谢夫&quot;，&quot;GetSeed&quot;可能变成&quot;get seed&quot;。</p><p>语音词库帮你解决这个问题：把你常用的词提前告诉 AI，录音转写时 AI 就会优先识别这些词，大幅提升准确率。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>行业术语</strong>：金融、法律、医疗、科技等领域的专业词汇，避免转写时被识别成同音别字</li><li><strong>人名识别</strong>：同事、客户、合作伙伴的姓名，特别是生僻字或容易混淆的名字</li><li><strong>产品/品牌名</strong>：公司内部产品代号、品牌名称、项目代号等专有名词</li><li><strong>外来词汇</strong>：英文缩写、外语人名、中英混用的表达，帮助 AI 正确识别</li><li><strong>学术场景</strong>：课程名称、学术概念、文献中的特定术语</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ul><li><strong>智能推荐热词</strong>：AI 基于你已有的笔记内容，自动分析并推荐高频出现但可能识别不准的词汇，一键添加即可</li><li><strong>自定义添加</strong>：手动创建并添加你需要的热词，输入正确写法，AI 在后续转写时会优先匹配</li><li><strong>提升识别率</strong>：词库中的词会在语音识别时被加权，遇到同音词时优先识别为你设定的正确写法</li></ul><h2 id="app端使用说明" tabindex="-1">APP端使用说明 <a class="header-anchor" href="#app端使用说明" aria-label="Permalink to &quot;APP端使用说明&quot;">​</a></h2><ol><li><p>打开 App，点首页右上角菜单，点头像进入「我的账号」页面，在常用操作区域点击「语音词库」</p></li><li><p>进入词库页面后，可以看到两个区域：AI 智能推荐的热词和自定义词库</p></li><li><p><strong>智能推荐</strong>：AI 会基于你的笔记内容分析出高频热词，点击即可一键添加到词库</p></li><li><p><strong>自定义添加</strong>：输入你需要的词汇（如人名、术语、品牌名），保存后即刻生效</p></li><li><p>设置完成后无需其他操作，后续录音转写时 AI 会自动应用词库，优先识别你添加的词汇</p></li><li><p>录音中，点击右上角设置按钮，也可进入语音词库</p></li></ol><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+e+'" alt="词库入口" style="width:180px;border-radius:8px;"><img src="'+l+'" alt="智能推荐" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="自定义添加" style="width:180px;border-radius:8px;"></div>',13)])])}const m=t(n,[["render",p]]);export{b as __pageData,m as default};
